Filter empty interpolated queries after applying variables

This now filters `query.expr` before interpolation, but `applyTemplateVariables` can expand an originally non-empty expression to an empty string (for example when the whole query is an unset variable). Such a target then reaches sharding classification/execution instead of being dropped like normal datasource queries. The empty-expression filter should run after template variables are applied.

Proposed patch:
```diff
--- a/public/app/plugins/datasource/loki/shardQuerySplitting.ts
+++ b/public/app/plugins/datasource/loki/shardQuerySplitting.ts
@@ -46,10 +46,10 @@ import { LokiQuery } from './types';
  */

 export function runShardSplitQuery(datasource: LokiDatasource, request: DataQueryRequest<LokiQuery>) {
   const queries = request.targets
-    .filter((query) => query.expr)
     .filter((query) => !query.hide)
-    .map((query) => datasource.applyTemplateVariables(query, request.scopedVars, request.filters));
+    .map((query) => datasource.applyTemplateVariables(query, request.scopedVars, request.filters))
+    .filter((query) => query.expr);

   return splitQueriesByStreamShard(datasource, request, queries);
 }

```

